1227	fn prescribed_coupled(system: &StructuralSystem<'_>, row: usize) -> bool {
1228	    system
1229	        .prescribed
1230	        .iter()
1231	        .any(|&(j, u)| system.stiffness[row][j] != 0.0 && u != 0.0)
1232	}
1233	/// KS1: `f_i - sum_c K_ic * g_c`, one exact sum scaled by `2^exponent` before
1234	/// its single rounding (S11 R3-4), with `radix_scale`'s range semantics.
1235	fn exact_scaled_rhs(
1236	    system: Equations<'_>,
1237	    binding: ForceBinding<'_>,
1238	    row: usize,
1239	    couplings: impl Iterator<Item = (f64, f64)>,
1240	    exponent: i32,
1241	) -> Result<f64, StructuralError> {
1242	    // K1: `couplings` are row's (K_ic, g_c) over the prescribed columns (the
1243	    // dense row passes all of them; the sparse row its stored ones). The sum
1244	    // is exact, so an absent (zero) K_ic changes nothing.
1245	    let mut accumulator = ExactAccumulator::new();
1246	    match binding.assembled() {
1247	        Some(force) => force
1248	            .accumulate_dof(row, &mut accumulator, false)
1249	            .map_err(sum_range)?,
1250	        None => accumulator.add(system.force[row]).map_err(sum_range)?,
1251	    }
1252	    for (k, u) in couplings {
1253	        accumulator.add_product(-k, u).map_err(sum_range)?;
1254	    }
1255	    if accumulator.round().is_err() {
1256	        return Err(StructuralError::Range("nonfinite radix input"));
1257	    }
1258	    let value = accumulator
1259	        .round_scaled(exponent)
1260	        .map_err(|_| StructuralError::Range("radix scaling loses normal range"))?;
1261	    if value.is_subnormal() || (value == 0.0 && !accumulator.is_zero()) {
1262	        return Err(StructuralError::Range("radix scaling loses normal range"));
1263	    }
1264	    Ok(value)
1265	}
1266	fn prepare_bound<'s>(
1267	    system: &'s StructuralSystem<'s>,
1268	    force_binding: ForceBinding<'s>,
1269	) -> Result<PreparedSystem<'s>, StructuralError> {
1270	    validate(system)?;
1271	    let n = system.free_dofs.len();
1272	    let mut exponents = Vec::with_capacity(n);
1273	    for &i in system.free_dofs {
1274	        let d = system.stiffness[i][i];
1275	        if d < 0.0 {
1276	            let mut direction = vec![0.0; system.force.len()];
1277	            direction[i] = 1.0;
1278	            return Err(StructuralError::NegativeEnergy {
1279	                direction,
1280	                energy: d,
1281	                allowance: 0.0,
1282	            });
1283	        }
1284	        if d == 0.0 {
1285	            return Err(unresolved(
1286	                "zero original diagonal; no physical nullity inferred",
1287	                Some(i),
1288	            ));
1289	        }
1290	        exponents.push(-binary_exponent(d).div_euclid(2));
1291	    }
1292	    let mut a = vec![vec![0.0; n]; n];
1293	    let mut rhs = vec![0.0; n];
1294	    for (r, &i) in system.free_dofs.iter().enumerate() {
1295	        for (c, &j) in system.free_dofs.iter().enumerate() {
1296	            a[r][c] = radix_scale(system.stiffness[i][j], exponents[r] + exponents[c])?;
1297	        }
1298	        if !force_binding.binary64()
1299	            && (force_binding.assembled().is_some() || prescribed_coupled(system, i))
1300	        {
1301	            rhs[r] = exact_scaled_rhs(
1302	                system.view(),
1303	                force_binding,
1304	                i,
1305	                system
1306	                    .prescribed
1307	                    .iter()
1308	                    .map(|&(j, u)| (system.stiffness[i][j], u)),
1309	                exponents[r],
1310	            )?;
1311	        } else {
1312	            // No nonzero prescribed product: today's evaluation, bit for bit.
1313	            let mut b = system.force[i];
1314	            for &(j, u) in system.prescribed {
1315	                b = checked_value(b - checked_product(system.stiffness[i][j], u)?)?;
1316	            }
1317	            rhs[r] = radix_scale(b, exponents[r])?;
1318	        }
1319	    }
1320	    let mut projection = false;
1321	    let mut max_skew: f64 = 0.0;
1322	    if let Some(evidence) = &system.symmetry {
1323	        let full = system.force.len();
1324	        if evidence.basis.is_empty()
1325	            || evidence.absolute_roundoff.len() != full
1326	            || evidence.operation_counts.len() != full
1327	            || evidence
1328	                .absolute_roundoff
1329	                .iter()
1330	                .any(|r| r.len() != full || r.iter().any(|v| !v.is_finite() || *v < 0.0))
1331	            || evidence.operation_counts.iter().any(|r| r.len() != full)
1332	        {
1333	            return Err(StructuralError::InvalidInput("symmetry provenance"));
1334	        }
1335	    }
1336	    for i in 0..n {
1337	        for j in 0..i {
1338	            let skew = checked_value(a[i][j] - a[j][i])?.abs();
1339	            max_skew = max_skew.max(skew);
1340	            if skew == 0.0 {
1341	                continue;
1342	            }
1343	            let allowed = if let Some(e) = &system.symmetry {
1344	                let gi = system.free_dofs[i];
1345	                let gj = system.free_dofs[j];
1346	                checked_value(
1347	                    radix_scale(e.absolute_roundoff[gi][gj], exponents[i] + exponents[j])?
1348	                        + radix_scale(e.absolute_roundoff[gj][gi], exponents[i] + exponents[j])?,
1349	                )?
1350	            } else {
1351	                0.0
1352	            };
1353	            if skew > allowed {
1354	                return Err(StructuralError::Asymmetric {
1355	                    row: system.free_dofs[i],
1356	                    col: system.free_dofs[j],
1357	                    relative_skew: skew / a[i][j].abs().max(a[j][i].abs()),
1358	                });
1359	            }
1360	            let average = a[i][j] / 2.0 + a[j][i] / 2.0;
1361	            a[i][j] = average;
1362	            a[j][i] = average;
1363	            projection = true;
1364	        }
1365	    }
1366	    let (perturbation, load_perturbation, rounding) =
1367	        audit_contributions(system, &exponents, &rhs)?;
1368	    Ok(PreparedSystem {
1369	        source: system,
1370	        force_binding,
1371	        formation: None,
1372	        matrix: a,
1373	        rhs,
1374	        scale_exponents: exponents,
1375	        assembly_relative_perturbation_estimate: perturbation,
1376	        assembly_load_perturbation_estimate: load_perturbation,
1377	        contribution_rounding: rounding,
1378	        symmetry_projection_performed: projection,
1379	        maximum_scaled_skew: max_skew,
1380	        symmetry_basis: system.symmetry.as_ref().map(|e| e.basis.to_owned()),
1381	    })
1382	}
